function adminSidebar(string $active,string $title,string $subtitle=''): void {
    $items=[['home.php','Dashboard','dashboard','⌂'],['student-list.php','Students','students','♙'],['teacher-list.php','Teachers','teachers','♧'],['attendance-log.php','Attendance logs','attendance','◷'],['settings.php','Settings','settings','⚙']];
    $items[]=['school-year-rollover.php','School year','rollover','SY'];
    $section=$active==='teachers'?'Teachers':($active==='students'?'Students':($active==='attendance'?'Attendance':($active==='rollover'?'School year':($active==='settings'?'Settings':'Dashboard'))));
    $toast=$_SESSION['toast']['message']??null; $toastType=$_SESSION['toast']['type']??'success'; $toastClass=$toastType==='error'?'bg-rose-600':'bg-emerald-600'; unset($_SESSION['toast']); ?>
<div class="min-h-screen lg:flex"><aside data-admin-nav class="fixed inset-y-0 left-0 z-40 flex w-72 -translate-x-full flex-col overflow-y-auto bg-slate-950 p-5 text-slate-200 transition-transform lg:sticky lg:top-0 lg:h-screen lg:translate-x-0"><a href="home.php" class="mb-9 flex items-center gap-3 px-2 text-lg font-bold text-white"><img src="../image/logo.png" alt="Maruhat National High School logo" class="h-10 w-10 rounded-xl bg-white object-contain p-0.5 shadow-sm"><span>Biometric<span class="text-blue-400">.</span><span class="block text-xs font-normal text-slate-400">Attendance system</span></span></a><nav class="space-y-1" aria-label="Admin navigation"><?php foreach($items as [$url,$label,$key,$icon]): ?><a href="<?= $url ?>" class="flex items-center gap-3 rounded-xl px-4 py-3 text-sm font-semibold transition <?= $active===$key?'bg-blue-600 text-white shadow-lg shadow-blue-900/30':'text-slate-300 hover:bg-slate-800 hover:text-white' ?>"><span class="grid h-6 w-6 place-items-center text-lg" aria-hidden="true"><?= $icon ?></span><?= $label ?></a><?php endforeach; ?></nav><a href="../common/logout.php" class="mt-auto flex items-center gap-3 rounded-xl border border-rose-400/40 bg-rose-500/10 px-4 py-3 text-sm font-bold text-rose-200 transition hover:bg-rose-500 hover:text-white"><span aria-hidden="true">↪</span>Sign out</a></aside><div data-admin-overlay class="fixed inset-0 z-30 hidden bg-slate-950/50 lg:hidden"></div><main class="min-w-0 flex-1"><header class="border-b border-slate-200 bg-white px-5 py-4 lg:px-8"><div class="flex items-center gap-4"><button data-admin-menu class="rounded-lg border border-slate-200 p-2 font-bold lg:hidden" aria-label="Open navigation" aria-expanded="false">☰</button><div class="min-w-0 flex-1"><?php if($active!=='dashboard'): ?><div class="flex flex-wrap items-center gap-2 text-xs font-semibold text-slate-400"><a href="home.php" class="hover:text-blue-600">Dashboard</a><span>/</span><span class="text-slate-600"><?= htmlspecialchars($section) ?></span><?php if($title!==$section): ?><span>/</span><span class="text-slate-600"><?= htmlspecialchars($title) ?></span><?php endif; ?></div><?php endif; ?><h1 class="mt-1 truncate text-xl font-bold text-slate-900"><?= htmlspecialchars($title) ?></h1><?php if($subtitle): ?><p class="mt-1 text-sm text-slate-500"><?= htmlspecialchars($subtitle) ?></p><?php endif; ?></div><div class="hidden text-right text-sm text-slate-500 sm:block"><span id="clock"></span></div></div><?php if($active!=='dashboard'): ?><a href="javascript:history.back()" class="mt-3 inline-flex items-center gap-1 text-sm font-bold text-blue-600 hover:text-blue-700">← Back</a><?php endif; ?></header><div class="mx-auto max-w-7xl p-5 lg:p-8">
<?php if($toast): ?><div data-auto-toast class="fixed bottom-5 right-5 z-50 rounded-xl <?= $toastClass ?> px-5 py-4 font-bold text-white shadow-xl transition-all duration-300" role="status"><?= htmlspecialchars($toast) ?></div><?php endif; ?>
<?php }
function adminFoot(): void { ?></div></main></div><script>const nav=document.querySelector('[data-admin-nav]'),overlay=document.querySelector('[data-admin-overlay]'),button=document.querySelector('[data-admin-menu]');function toggle(open){nav?.classList.toggle('-translate-x-full',!open);overlay?.classList.toggle('hidden',!open);button?.setAttribute('aria-expanded',open)}button?.addEventListener('click',()=>toggle(nav.classList.contains('-translate-x-full')));overlay?.addEventListener('click',()=>toggle(false));document.addEventListener('keydown',e=>{if(e.key==='Escape')toggle(false)});const clock=document.getElementById('clock');if(clock){const tick=()=>clock.textContent=new Date().toLocaleString([], {dateStyle:'medium',timeStyle:'short'});tick();setInterval(tick,60000)}document.querySelectorAll('[data-auto-toast]').forEach(toast=>setTimeout(()=>{toast.classList.add('translate-y-3','opacity-0');setTimeout(()=>toast.remove(),300)},4000));const studentDeleteButton=document.getElementById('delete-button'),studentDeleteForm=document.getElementById('delete-form');if(studentDeleteButton&&studentDeleteForm){const modal=document.createElement('div');modal.id='delete-student-modal';modal.className='fixed inset-0 z-50 hidden items-center justify-center bg-slate-950/60 p-5';modal.innerHTML='<div class="w-full max-w-sm rounded-2xl bg-white p-6 shadow-2xl"><h3 class="text-xl font-black text-slate-900">Delete student account?</h3><p class="mt-2 text-sm text-slate-500">This permanently removes the student profile and biometric image.</p><div class="mt-6 flex gap-3"><button type="button" id="cancel-delete-student" class="flex-1 rounded-xl border border-slate-300 px-4 py-3 font-bold">Cancel</button><button type="button" id="confirm-delete-student" class="flex-1 rounded-xl bg-rose-600 px-4 py-3 font-bold text-white">Delete</button></div></div>';document.body.appendChild(modal);studentDeleteButton.onclick=()=>modal.classList.replace('hidden','flex');document.getElementById('cancel-delete-student').onclick=()=>modal.classList.replace('flex','hidden');document.getElementById('confirm-delete-student').onclick=()=>studentDeleteForm.submit()}</script></body></html><?php }
